(7267379, 1130617, 13077, '<td valign="top">Very striking and cool flowers. Not crazy about the composition personally, and there seems to be some motion blur as well.</td>', 'Very striking and cool flowers. Not crazy about the composition personally, and there seems to be some motion blur as well.', '2014-09-29 12:21:17.000000', NULL, 1),
(7267386, 1130585, 13077, '<td valign="top">I like all the details and shapes here. Outtake for the food in B&amp;W challenge?</td>', 'I like all the details and shapes here. Outtake for the food in B&W challenge?', '2014-09-29 12:41:46.000000', NULL, 1),
(7267387, 1130358, 13077, '<td valign="top">That''s a big ''un. The geometry is front and center, and the rest of the photo supports it well.</td>', 'That''s a big ''un. The geometry is front and center, and the rest of the photo supports it well.', '2014-09-29 12:43:00.000000', NULL, 1),
(7267404, 1130132, 118154, '<td valign="top">Good stuff</td>', 'Good stuff', '2014-09-29 13:10:28.000000', NULL, 1),
