(7267582, 1130544, 13077, '<td valign="top">Very nice. Great contrast and sharpness, nice grittiness as well.</td>', 'Very nice. Great contrast and sharpness, nice grittiness as well.', '2014-09-29 23:31:29.000000', NULL, 1),
