(7267584, 1130200, 13077, '<td valign="top">Ouch! Sharp in more ways than one.</td>', 'Ouch! Sharp in more ways than one.', '2014-09-29 23:32:04.000000', NULL, 1),
(7267585, 1130616, 13077, '<td valign="top">Very cool. Curious to see where this is. I like the dramatic clouds as well as the building.</td>', 'Very cool. Curious to see where this is. I like the dramatic clouds as well as the building.', '2014-09-29 23:32:24.000000', NULL, 1),
(7267586, 1130561, 13077, '<td valign="top">I like the gradiation of shadow to light here, and well composed.</td>', 'I like the gradiation of shadow to light here, and well composed.', '2014-09-29 23:33:30.000000', NULL, 1),
(7267587, 1130574, 13077, '<td valign="top">I like this - simple and low-key, but excellent detail and the light really brings out the color well.</td>', 'I like this - simple and low-key, but excellent detail and the light really brings out the color well.', '2014-09-29 23:33:51.000000', NULL, 1),
(7267588, 1130271, 13077, '<td valign="top">Nice details and very well composed and toned.</td>', 'Nice details and very well composed and toned.', '2014-09-29 23:34:05.000000', NULL, 1),
(7267589, 1130493, 13077, '<td valign="top">Very interesting. The composition presents it well.</td>', 'Very interesting. The composition presents it well.', '2014-09-29 23:34:23.000000', NULL, 1),
