(7267591, 1130494, 13077, '<td valign="top">Excellent overall - the light is great, focus is well placed and the processing looks good.</td>', 'Excellent overall - the light is great, focus is well placed and the processing looks good.', '2014-09-29 23:35:08.000000', NULL, 1),
