(7267594, 1130540, 13077, '<td valign="top">I like this - simple and visually bold, looks like a real-life cartoon.</td>', 'I like this - simple and visually bold, looks like a real-life cartoon.', '2014-09-29 23:36:30.000000', NULL, 1),
(7267595, 1130587, 13077, '<td valign="top">Lots of geometry to be found here, and well presented with contrasty light.</td>', 'Lots of geometry to be found here, and well presented with contrasty light.', '2014-09-29 23:36:59.000000', NULL, 1),
(7267596, 1130139, 13077, '<td valign="top">Excellent job making one of these look interesting.</td>', 'Excellent job making one of these look interesting.', '2014-09-29 23:37:21.000000', NULL, 1),
