(7267841, 1130616, 124815, '<td valign="top">now that you put it this way and treated it monochromatically, it is a bit of an undulated mushroom</td>', 'now that you put it this way and treated it monochromatically, it is a bit of an undulated mushroom', '2014-09-30 21:16:01.000000', NULL, 1),
(7268399, 1130526, 96311, '<td valign="top">My thoughts.......Spider is to close to edge imo, i would of cloned out the dead bug,(one main subject instead of 2) i would of tried misting the web with water n used off camera flash to try n make the web stand out more. tried a web shot with no spider, maybe played with hue/saturation n contrast to try seperate the web from the background. <br/>Rob</td>', 'My thoughts.......Spider is to close to edge imo, i would of cloned out the dead bug,(one main subject instead of 2) i would of tried misting the web with water n used off camera flash to try n make the web stand out more. tried a web shot with no spider, maybe played with hue/saturation n contrast to try seperate the web from the background. Rob', '2014-10-01 15:54:03.000000', NULL, 1),
(7268404, 1130606, 96311, '<td valign="top">would of preferred the focus to be on the onion instead of the grater</td>', 'would of preferred the focus to be on the onion instead of the grater', '2014-10-01 16:05:15.000000', NULL, 1),
(7268639, 1130615, 61396, '<td valign="top">+1 for making me look deeper</td>', '+1 for making me look deeper', '2014-10-02 16:23:17.000000', NULL, 1),
(7268645, 1130354, 150277, '<td valign="top">Very interesting detail you captured, looks a bit like an x-ray.</td>', 'Very interesting detail you captured, looks a bit like an x-ray.', '2014-10-02 16:38:06.000000', NULL, 1),
